'use strict';

/**
 * kppdf-frontend-architecture / no-raw-http-in-components (CommonJS)
 *
 * Forbids raw HttpClient use in `*.page.ts` and `*.component.ts` files.
 *
 * Why:
 *   Per TZ-232 §1.1 + §1.2, all HTTP from components must flow through:
 *     - `defineEntity<T,P>()` services generated by TZ-232.B
 *     - `httpResource()` signal-based fetch (Angular 20 native)
 *
 *   Direct `HttpClient` import or `this.http.<verb>(...)` calls in components
 *   leak raw HTTP/JSON concerns into the view layer, bypassing:
 *     - type safety (T identity vs Partial<T>)
 *     - error envelope mapping (SilentResult<T>)
 *     - submit guards / idempotency middleware (TZ-232.N)
 *
 * Allowed paths:
 *   - `*.service.ts`                  → may import HttpClient
 *   - `*.interceptor.ts`              → may import HttpClient
 *   - non-component .ts files         → may import HttpClient
 *
 * Tests: ./no-raw-http-in-components.spec.cjs (3 PASS + 2 FAIL fixtures)
 */

const RAW_HTTP_METHODS = new Set([
  'get', 'post', 'put', 'patch', 'delete', 'head', 'options',
]);

module.exports = {
  meta: {
    type: 'problem',
    docs: {
      description:
        'Forbid raw HttpClient use in `*.page.ts` or `*.component.ts` (use defineEntity() services or httpResource() instead).',
      recommended: 'warn',
    },
    schema: [],
    messages: {
      noRawHttpImport:
        'HttpClient import is forbidden in component/page files. Use defineEntity() services or httpResource() instead.',
      noRawHttpCall:
        'Raw `this.http.<method>()` call is forbidden in component/page files. Use defineEntity() services or httpResource() instead.',
    },
  },

  create(context) {
    const filename = context.filename || '';

    // Scope gate: only files matching component conventions.
    if (
      !filename.endsWith('.page.ts') &&
      !filename.endsWith('.component.ts')
    ) {
      return {};
    }

    return {
      // Pattern 1: `import { HttpClient } from '@angular/common/http'`.
      ImportDeclaration(node) {
        if (
          node.source.value !== '@angular/common/http' ||
          node.importKind !== 'value'
        ) {
          return;
        }
        for (const spec of node.specifiers) {
          if (
            spec.type === 'ImportSpecifier' &&
            spec.imported.type === 'Identifier' &&
            spec.imported.name === 'HttpClient'
          ) {
            context.report({ node: spec, messageId: 'noRawHttpImport' });
          }
        }
      },

      // Pattern 2: `this.http.<method>(...)` (scoped to component files).
      CallExpression(node) {
        const callee = node.callee;
        if (
          callee.type !== 'MemberExpression' ||
          callee.object.type !== 'MemberExpression' ||
          callee.object.object.type !== 'ThisExpression' ||
          callee.object.property.type !== 'Identifier' ||
          callee.object.property.name !== 'http' ||
          callee.property.type !== 'Identifier' ||
          !RAW_HTTP_METHODS.has(callee.property.name)
        ) {
          return;
        }
        context.report({ node: callee, messageId: 'noRawHttpCall' });
      },
    };
  },
};
